<script>
(() => {
    const font = document.getElementById('font_family'), preview = document.getElementById('fontPreview');
    @foreach($fonts as $customFont) { const style{{ $customFont->id }} = document.createElement('style'); style{{ $customFont->id }}.textContent = `@font-face{font-family:'{{ $customFont->name }}';src:url('{{ $customFont->url() }}')}`; document.head.appendChild(style{{ $customFont->id }}); } @endforeach
    const updateFont = () => { preview.style.fontFamily = font.value; document.querySelectorAll('.preview-page').forEach(el => el.style.fontFamily = font.value); };
    font.addEventListener('change', updateFont); updateFont();
    ['front','back'].forEach(side => document.getElementById('background_'+side).addEventListener('change', e => { const file=e.target.files[0]; if(file) document.getElementById('preview-'+side).style.backgroundImage=`url('${URL.createObjectURL(file)}')`; }));
    document.querySelectorAll('.remove-bg').forEach(btn => btn.addEventListener('click', () => { if(confirm('Hapus background ini?')) document.getElementById('remove-'+btn.dataset.side).submit(); }));
    document.querySelectorAll('.remove-font').forEach(btn => btn.addEventListener('click', () => { if(confirm('Hapus font custom ini?')) document.getElementById('remove-font-'+btn.dataset.id).submit(); }));
    const canvas=document.getElementById('designerCanvas'), layoutInput=document.getElementById('design_layout'), layout=JSON.parse(layoutInput.value||'{}'), items=[...canvas.querySelectorAll('.design-item')], list=document.getElementById('elementList'), size=document.getElementById('elementSize'), sizeValue=document.getElementById('sizeValue'), elementFont=document.getElementById('elementFont'), elementWeight=document.getElementById('elementWeight'), elementItalic=document.getElementById('elementItalic'), elementColor=document.getElementById('elementColor'), colorValue=document.getElementById('colorValue'), canvasOffsetX=document.getElementById('canvasOffsetX'); let selected=null, dragging=false, offset={x:0,y:0};
    layout._canvas=layout._canvas||{offset_x:-75};canvasOffsetX.value=layout._canvas.offset_x;
    const sync=()=>layoutInput.value=JSON.stringify(layout); const canvasScale=()=>canvas.clientWidth/1123; const isCentered=item=>['nama','identitas','perusahaan'].includes(item.dataset.key); const applyStyle=(item,l)=>{const centered=isCentered(item);item.style.left=centered?'0':l.x+'%';item.style.width=centered?'100%':'auto';item.style.textAlign=centered?'center':'left';item.style.transform=centered?'none':`translateX(${layout._canvas.offset_x*canvasScale()}px)`;item.style.top=l.y+'%';item.style.fontSize=(l.size*canvasScale())+'px';item.style.fontFamily=l.font;item.style.fontWeight=l.weight;item.style.fontStyle=l.italic?'italic':'normal';item.style.color=l.color}; const redraw=()=>items.forEach(item=>applyStyle(item,layout[item.dataset.key])); const select=item=>{selected=item;const l=layout[item.dataset.key];items.forEach(i=>i.classList.toggle('selected',i===item));[...list.children].forEach(b=>b.classList.toggle('active',b.dataset.key===item.dataset.key));size.value=l.size;sizeValue.textContent=size.value+' px';elementFont.value=l.font;elementWeight.value=l.weight;elementItalic.checked=!!l.italic;elementColor.value=l.color;colorValue.textContent=l.color};
    items.forEach(item=>{const key=item.dataset.key,l=layout[key]||{x:10,y:10,size:14};l.font=l.font||font.value;l.weight=l.weight||400;l.italic=!!l.italic;l.color=l.color||'#1f2937';layout[key]=l;applyStyle(item,l);const b=document.createElement('button');b.type='button';b.dataset.key=key;b.textContent=item.textContent;b.onclick=()=>select(item);list.appendChild(b);item.addEventListener('pointerdown',e=>{select(item);dragging=true;const r=item.getBoundingClientRect();offset={x:e.clientX-r.left,y:e.clientY-r.top};item.setPointerCapture(e.pointerId)})});
    canvas.addEventListener('pointermove',e=>{if(!dragging||!selected)return;const r=canvas.getBoundingClientRect();const displayedX=(e.clientX-r.left-offset.x)/r.width*100,offsetPercent=layout._canvas.offset_x/1123*100;let x=isCentered(selected)?0:displayedX-offsetPercent,y=(e.clientY-r.top-offset.y)/r.height*100;x=Math.max(0,Math.min(96,x));y=Math.max(0,Math.min(94,y));layout[selected.dataset.key].x=+x.toFixed(2);layout[selected.dataset.key].y=+y.toFixed(2);applyStyle(selected,layout[selected.dataset.key]);sync()});canvas.addEventListener('pointerup',()=>dragging=false);size.addEventListener('input',()=>{if(!selected)return;layout[selected.dataset.key].size=+size.value;sizeValue.textContent=size.value+' px';applyStyle(selected,layout[selected.dataset.key]);sync()});elementFont.addEventListener('change',()=>{if(!selected)return;layout[selected.dataset.key].font=elementFont.value;applyStyle(selected,layout[selected.dataset.key]);sync()});elementWeight.addEventListener('change',()=>{if(!selected)return;layout[selected.dataset.key].weight=+elementWeight.value;applyStyle(selected,layout[selected.dataset.key]);sync()});elementItalic.addEventListener('change',()=>{if(!selected)return;layout[selected.dataset.key].italic=elementItalic.checked;applyStyle(selected,layout[selected.dataset.key]);sync()});elementColor.addEventListener('input',()=>{if(!selected)return;layout[selected.dataset.key].color=elementColor.value;colorValue.textContent=elementColor.value;applyStyle(selected,layout[selected.dataset.key]);sync()});canvasOffsetX.addEventListener('input',()=>{layout._canvas.offset_x=Math.max(-200,Math.min(200,+canvasOffsetX.value||0));redraw();sync()});new ResizeObserver(redraw).observe(canvas);select(items[0]);redraw();sync();
})();
</script>
